sn_aia_tool.script:
(function(inputs) {
    var watchlistGr = new GlideRecordSecure('x_aleen_snguardian_visitor_watch_list');
    watchlistGr.addQuery('email', inputs.visitor_email);
    watchlistGr.addQuery('location', inputs.user_location);
    watchlistGr.query();
    if(watchlistGr.next()){
        return {
            "success": false,
            "message": "Visitor found Watchlisted"
        };
    }else{
        var response = {};
        response.success = true;
        response.message = "Visitor not found Watchlisted";
        var visitorGr = new GlideRecordSecure('x_aleen_snguardian_visitor');
        visitorGr.addQuery('email', inputs.visitor_email);
        visitorGr.query();
        if(visitorGr.next()){
            response.existing_visitor = true;
            response.visitor_sys_id = visitorGr.getValue('sys_id');
        }
        return response;
    }
})(inputs);
